import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { existsSync, readFileSync, readdirSync, realpathSync } from 'node:fs'
import { createRequire } from 'node:module'
import { basename, dirname, join, relative, resolve, sep } from 'node:path'

// These two files are generated by pnpm 11, not published in the SDK archive.
// Their provider metadata and CLI bytes are pinned to the verified official tar.
// No directory is excluded: every other installed entry still fails inventory.
const reviewedSdkBinShims = [
  [
    'vtkDataConverter',
    'Utilities/DataGenerator/convert-cli.js',
    3250,
    '540a84c2c0565b69ee7f087f145ccfb6ca06598832d27c48ad7a704843606b7c'
  ],
  [
    'xml2json',
    'Utilities/XMLConverter/xml2json-cli.js',
    911,
    '5207427e06b6351921cce2cc170335981a6aa5eed27d611863215216e52c6ff3'
  ]
].map(([name, path, bytes, sha256]) => ({
  path: `node_modules/.bin/${name}`,
  provider: '@kitware/vtk.js',
  version: '36.4.1',
  providerManifest: {
    path: 'package.json',
    bytes: 5740,
    sha256: 'c1c2d245b4af9fc5635637608176a56a4788d411154d9dd89e3c4444ed25f989'
  },
  providerBin: { path, bytes, sha256 },
  integrity:
    'sha512-vHgiOZTHS7wgEw6Cbuv6vS+zlTx8HgepPqq0UMTWx6T+OcmP2qJCGRpHI1eTPqKcN2SaEHIK7DSsVatTHZ9OPw==',
  normalizedShimSHA256: 'a220a8e6c4f9dae2194ded89882e49b84a5faa9c673667898ff7837f62e22f5b'
}))

function verifyGeneratedSdkBins(packagePath, artifact, manifest) {
  const expected =
    artifact.name === '@cornerstonejs/core' && artifact.version === '5.13.2'
      ? reviewedSdkBinShims
      : []
  assert.deepEqual(
    artifact.installationGeneratedBinShims ?? [],
    expected,
    'Reviewed installation-generated bin records drifted'
  )
  const require = createRequire(join(packagePath, 'package.json'))
  for (const record of expected) {
    const providerPath = dirname(realpathSync(require.resolve(`${record.provider}/package.json`)))
    for (const file of [record.providerManifest, record.providerBin]) {
      const bytes = readFileSync(join(providerPath, file.path))
      assert.equal(bytes.length, file.bytes, 'Generated bin provider size drifted')
      assert.equal(
        createHash('sha256').update(bytes).digest('hex'),
        file.sha256,
        'Generated bin provider bytes drifted'
      )
    }
    const provider = JSON.parse(readFileSync(join(providerPath, 'package.json'), 'utf8'))
    assert.equal(provider.name, record.provider, 'Generated bin provider name drifted')
    assert.equal(provider.version, record.version, 'Generated bin provider version drifted')
    assert.equal(
      manifest.dependencies[record.provider],
      record.version,
      'Generated bin must come from the exact SDK dependency'
    )
    assert.equal(
      provider.bin[basename(record.path)],
      record.providerBin.path,
      'Generated bin target declaration drifted'
    )
    const shimPath = join(packagePath, record.path)
    const target = join(providerPath, record.providerBin.path)
    const alias = join(dirname(dirname(packagePath)), record.provider, record.providerBin.path)
    const aliasBindings = []
    if (existsSync(alias)) {
      assert.equal(
        realpathSync(alias),
        realpathSync(target),
        'Generated bin alias must resolve to the verified provider'
      )
      aliasBindings.push(
        [relative(dirname(shimPath), alias).split(sep).join('/'), '<relative-bin>'],
        [alias, '<provider-bin>']
      )
    }
    // Only the exact installation paths are variable. All shell code, flags,
    // target references and environment handling must match the reviewed shim.
    const bindings = [
      ...aliasBindings,
      [relative(dirname(shimPath), target).split(sep).join('/'), '<relative-bin>'],
      [target, '<provider-bin>'],
      [join(providerPath, 'node_modules'), '<provider-node-modules>'],
      [dirname(dirname(providerPath)), '<provider-sibling-node-modules>'],
      [join(resolve(providerPath, '../../../..'), 'node_modules'), '<pnpm-node-modules>']
    ]
    let normalized = readFileSync(shimPath, 'utf8')
    for (const [path, label] of bindings) normalized = normalized.replaceAll(path, label)
    assert.equal(
      createHash('sha256').update(normalized).digest('hex'),
      record.normalizedShimSHA256,
      'Generated bin shim bytes drifted'
    )
  }
  return expected.map((record) => record.path)
}

export function verifyCodecArtifact(packagePath, artifact) {
  const manifest = JSON.parse(readFileSync(join(packagePath, 'package.json'), 'utf8'))
  assert.equal(manifest.name, artifact.name, 'Native codec package name drifted')
  assert.equal(manifest.version, artifact.version, 'Native codec version drifted')
  // Modern tarballs omit gitHead. Their metadata, glue and WASM bytes still
  // have to match the complete reviewed official artifact, including this file.
  if (manifest.gitHead !== undefined) {
    assert.equal(manifest.gitHead, artifact.gitHead, 'Native codec gitHead drifted')
  }
  const generatedBins = verifyGeneratedSdkBins(packagePath, artifact, manifest)
  const filesIn = (directory, prefix = '') =>
    readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
      const path = prefix + entry.name
      if (entry.isDirectory()) return filesIn(join(directory, entry.name), path + '/')
      assert.ok(entry.isFile(), `${artifact.package}: unreviewed non-file entry: ${path}`)
      return [path]
    })
  assert.deepEqual(
    filesIn(packagePath).sort(),
    [...artifact.files.map((file) => file.path), ...generatedBins].sort(),
    `${artifact.package}: artifact file inventory drifted`
  )
  for (const file of artifact.files) {
    const actual = createHash('sha256')
      .update(readFileSync(join(packagePath, file.path)))
      .digest('hex')
    assert.equal(actual, file.sha256, `${artifact.package}: artifact bytes drifted: ${file.path}`)
  }
}

export function verifyCodecLockIntegrity(lockfile, artifact) {
  const packages = lockfile.slice(lockfile.indexOf('\npackages:\n'))
  const marker = `\n  '${artifact.package}':\n`
  const start = packages.indexOf(marker)
  assert.ok(start >= 0, `Missing reviewed lockfile codec: ${artifact.package}`)
  const remaining = packages.slice(start + marker.length)
  const nextEntry = remaining.search(/\n  \S/)
  const entry = nextEntry < 0 ? remaining : remaining.slice(0, nextEntry)
  const integrity = entry.match(/integrity:\s*([^\s,}]+)/)?.[1]
  assert.equal(integrity, artifact.integrity, `${artifact.package}: lockfile integrity drifted`)
  for (const provider of new Map(
    (artifact.installationGeneratedBinShims ?? []).map((record) => [record.provider, record])
  ).values()) {
    verifyCodecLockIntegrity(lockfile, {
      package: `${provider.provider}@${provider.version}`,
      integrity: provider.integrity
    })
  }
}

export function verifyCodecSourceLicenses(packagePath, provenance) {
  const expected = [
    [
      '@cornerstonejs/codec-libjpeg-turbo-8bit',
      '1.2.7',
      'ISC',
      '5c48f12a598db126de66c07779ac764ee1a3bc42',
      '3f122136bfdfff94ce7c5be92c62ae129c182fda'
    ],
    [
      '@cornerstonejs/codec-openjpeg',
      '1.3.6',
      'MIT',
      '5c48f12a598db126de66c07779ac764ee1a3bc42',
      '3f122136bfdfff94ce7c5be92c62ae129c182fda'
    ],
    [
      '@cornerstonejs/codec-libjxl',
      '1.1.1',
      'BSD-3-Clause',
      'c44693e9c96a126cb100b2c56ebfb7cad1e0a428',
      'c9ffa62a82e837485fd9fc918555e340e8d0402a'
    ]
  ].map(([name, version, declaredLicense, gitCommit, buildGitCommit]) => ({
    name,
    version,
    declaredLicense,
    sourceLicense: 'MIT',
    repository: 'https://github.com/cornerstonejs/codecs',
    gitCommit,
    buildGitCommit,
    sourcePath: 'LICENSE',
    path: 'third-party/native-codecs/wrapper/LICENSE',
    bytes: 1087,
    sha256: '456823558d5aee9aaed81428f9eb90d97c85ba0f770975b7ccff9ce12ef61438'
  }))
  assert.deepEqual(
    provenance.wrapperSourceLicenses,
    expected,
    'Reviewed codec source-license records drifted'
  )
  return expected.map((entry) => {
    const artifact = provenance.wrapperArtifacts.find((artifact) => artifact.name === entry.name)
    assert.equal(artifact?.version, entry.version, 'Source-license artifact version drifted')
    assert.equal(artifact.gitHead, entry.gitCommit, 'Source-license release commit drifted')
    assert.equal(
      artifact.buildProvenance.gitCommit,
      entry.buildGitCommit,
      'Source-license build commit drifted'
    )
    const filePath = join(packagePath, entry.path)
    const text = readFileSync(filePath)
    assert.equal(text.length, entry.bytes, 'Retained codec source-license size drifted')
    assert.equal(
      createHash('sha256').update(text).digest('hex'),
      entry.sha256,
      'Retained codec source-license hash drifted'
    )
    return { ...entry, filePath }
  })
}

export function verifyDicomSourceLicenses(packagePath, provenance) {
  const wrapper = verifyCodecSourceLicenses(packagePath, provenance)
  const expected = ['@cornerstonejs/core', '@cornerstonejs/metadata', '@cornerstonejs/utils'].map(
    (name) => ({
      name,
      version: '5.13.2',
      declaredLicense: 'MIT',
      sourceLicense: 'MIT',
      repository: 'https://github.com/cornerstonejs/cornerstone3D',
      gitCommit: '2adf417c1c2762e6bafc6ed29fad1b82ed0ed8cf',
      buildGitCommit: '0cae0c3564ad81d3c62422cc663e500844f0ef13',
      sourcePath: 'LICENSE',
      path: 'third-party/native-codecs/sdk/LICENSE',
      bytes: 1087,
      sha256: '456823558d5aee9aaed81428f9eb90d97c85ba0f770975b7ccff9ce12ef61438'
    })
  )
  assert.deepEqual(
    provenance.sdkSourceLicenses,
    expected,
    'Reviewed SDK source-license records drifted'
  )
  const sdk = expected.map((entry) => {
    const artifact = provenance.sdkArtifacts.find((artifact) => artifact.name === entry.name)
    assert.equal(artifact?.version, entry.version, 'SDK source-license artifact version drifted')
    assert.equal(artifact.gitHead, entry.gitCommit, 'SDK source-license release commit drifted')
    assert.equal(
      artifact.buildProvenance.gitCommit,
      entry.buildGitCommit,
      'SDK source-license build commit drifted'
    )
    const filePath = join(packagePath, entry.path)
    const bytes = readFileSync(filePath)
    assert.equal(bytes.length, entry.bytes, 'Retained SDK source-license size drifted')
    assert.equal(
      createHash('sha256').update(bytes).digest('hex'),
      entry.sha256,
      'Retained SDK source-license hash drifted'
    )
    return { ...entry, filePath }
  })
  return [...wrapper, ...sdk]
}
